func TestRecordCannotCarryFreeFormContent(t *testing.T) {
	t.Parallel()

	rt := reflect.TypeOf(audit.Record{})
	want := []string{"Action", "Caller", "SessionID", "Decision", "Reason", "Remote"}
	if rt.NumField() != len(want) {
