func (f *Fake) SendKeys(_ context.Context, name string, keys ...string) error {
	f.mu.Lock()
	defer f.mu.Unlock()

	f.record(OpSendKeys, argvSendKeys(name, keys...), nil)
	if err := f.fail[OpSendKeys]; err != nil {
		return err
	}
	s, ok := f.sessions[name]
	if !ok {
		return errNoSession(name)
	}
	for _, key := range keys {
		if key != "C-c" {
			continue
		}
		s.interrupts++
		if s.quitAfter > 0 && s.interrupts == s.quitAfter {
			s.paneCommand = "bash"
		}
	}
	return nil
}

// QuitAfterInterrupts makes the n-th "C-c" sent to name end its process: the
// pane's command becomes the login shell, as it does when Codex exits. The
// count starts from zero when this is called. It seeds the session if it does
// not exist yet, as SetPane does.
func (f *Fake) QuitAfterInterrupts(name string, n int) {
	f.mu.Lock()
	defer f.mu.Unlock()

	s, ok := f.sessions[name]
	if !ok {
		s = &fakeSession{paneCommand: fakeAliveCommand, options: make(map[string]string)}
		f.sessions[name] = s
	}
	s.quitAfter = n
	s.interrupts = 0
}

// Paste records two calls, as the real controller runs two commands. The
// payload is copied onto the load-buffer call's Stdin and never reaches Argv.
func (f *Fake) Paste(_ context.Context, name string, payload []byte) error {
	f.mu.Lock()
	defer f.mu.Unlock()

	buffer := f.nextBuffer()
	f.record(OpPaste, argvLoadBuffer(buffer), append([]byte(nil), payload...))
	f.record(OpPaste, argvPasteBuffer(buffer, name), nil)
	// The real controller deletes the buffer when paste-buffer fails, since -d
	// only runs on success.
	if err := f.fail[OpPaste]; err != nil {
		f.record(OpPaste, argvDeleteBuffer(buffer), nil)
		return err
	}
	if _, ok := f.sessions[name]; !ok {
		f.record(OpPaste, argvDeleteBuffer(buffer), nil)
		return errNoSession(name)
	}
	return nil
}

// PasteBracketed records the same two calls Paste does, under its own op, with
// the second carrying -p.
func (f *Fake) PasteBracketed(_ context.Context, name string, payload []byte) error {
	f.mu.Lock()
	defer f.mu.Unlock()

	buffer := f.nextBuffer()
	f.record(OpPasteBracketed, argvLoadBuffer(buffer), append([]byte(nil), payload...))
	f.record(OpPasteBracketed, argvPasteBufferBracketed(buffer, name), nil)
	// The real controller deletes the buffer when paste-buffer fails, since -d
	// only runs on success.
	if err := f.fail[OpPasteBracketed]; err != nil {
		f.record(OpPasteBracketed, argvDeleteBuffer(buffer), nil)
		return err
	}
	if _, ok := f.sessions[name]; !ok {
		f.record(OpPasteBracketed, argvDeleteBuffer(buffer), nil)
		return errNoSession(name)
	}
	return nil
}

