// claimRestart takes the single-restart claim for a session, and reports whether
// it got it (spec 013, FR-012).
//
// Two things restart a session's process: the supervisor reviving one that died,
// and an operator continuing a different conversation. Both interrupt the pane
// and type a start command into it, so exactly one may be doing that at a time —
// the alternative is two Claude processes in one shell, which is a session with
// two of everything and an operator watching whichever one draws last.
//
// The map is created lazily so a Manager built by a struct literal, or by a test
// that predates this field, is still a working Manager.
func (m *Manager) claimRestart(id string) bool {
	m.restartingMu.Lock()
	defer m.restartingMu.Unlock()

	if m.restarting == nil {
		m.restarting = make(map[string]bool)
	}
	if m.restarting[id] {
		return false
	}
	m.restarting[id] = true
	return true
}

func (m *Manager) releaseRestart(id string) {
	m.restartingMu.Lock()
	defer m.restartingMu.Unlock()
	delete(m.restarting, id)
}

// Continue points a running session at a prior conversation from its own working
// directory (spec 013, FR-006).
//
// # It restarts a process, never a session
//
// Everything about the session survives: its identity, its owner, the credential
// its owner holds, its working directory, its start command, when it was created
// and therefore when it expires. What changes is which conversation the thing
// inside the pane is having. That distinction is the whole of why this is not a
// create, and it is what keeps Principle VI's bounds intact — a session that
// could refresh its own deadline by continuing something would be a session with
// no deadline at all.
//
// # Why the directory is not a parameter
//
// The conversations an operator may continue are the ones in *this session's*
// recorded working directory. Taking a directory from the caller would let a
// session started in one place resume work from another, which is a way around
// the allowlist rather than a convenience.
//
// # The order is the contract
//
// The record, the tmux option and the journal are written *before* the pane is
// touched. A daemon that died between the two comes back knowing which
// conversation this session is on, and its supervisor revives it into that one.
// Written after, the same crash leaves a session running a conversation nothing
// has recorded.
func (m *Manager) Continue(ctx context.Context, s Session, conversationID string) (Session, error) {
	// Before any store, option, journal or pane change: a harness with no resume
	// flag has nothing to continue into, and finding that out after the quit
	// would already have interrupted a working pane.
	if harness.For(m.specOf(s).Name).ResumeArgs == nil {
		return Session{}, fmt.Errorf("continue session %s: %w", s.ID, ErrInvalidResume)
	}
	// Validated before anything else, because the value is caller-supplied and
	// its next stop is a command line typed into a live shell. ResumeLatest no
	// longer exists, so "latest" fails here exactly as any other unrecognised
	// value does (spec 013, FR-016).
	checked, err := ValidateResume(conversationID)
	if err != nil {
		return Session{}, fmt.Errorf("continue session %s: %w", s.ID, err)
	}
	if !isConversationID(checked) {
		return Session{}, fmt.Errorf("continue session %s: %w: it is not a conversation identifier", s.ID, ErrInvalidResume)
	}

	// A session that is not running has nothing to continue into. Both terminal
	// states are refused, and the sentinel is the one every caller already reads.
	if s.State == StateDead || s.State == StateFailed {
		return Session{}, fmt.Errorf("continue session %s: %w", s.ID, ErrSessionDead)
	}

	// The allowlist may have shrunk since this session was created. A directory
	// it no longer covers is one this daemon may not start work in, whether the
	// shell is already there or not.
	if _, err := m.workDir(s.WorkDir); err != nil {
		return Session{}, fmt.Errorf("continue session %s: %w", s.ID, err)
	}

	// Resuming an identifier with no transcript behind it does not fail — it
	// starts something that is not the conversation the operator asked for, which
	// is worse than refusing.
	if !m.hasTranscriptFor(s, checked) {
		return Session{}, fmt.Errorf("continue session %s: %w: there is no such conversation on this host", s.ID, ErrInvalidResume)
	}

	if !m.claimRestart(s.ID) {
		return Session{}, fmt.Errorf("continue session %s: %w", s.ID, ErrRestartInFlight)
	}
	defer m.releaseRestart(s.ID)

	// From here to the start line: the shell Continue verified is not to be
	// typed into, or restarted under, by any other operation on this session.
	unlock := m.lockSession(s.ID)
	defer unlock()

	// Touch first, and this is where Continue differs from a revival: a human
	// asked for this, so it is a driving like a prompt or a compact. Touch is
	// also the store's own answer, under the store's lock, to whether this record
	// is still there and still live — a session the reaper collected between the
	// caller's View and this call is refused here, before the pane is touched.
	now := m.clock.Now()
	if err := m.store.Touch(s.ID, now); err != nil {
		return Session{}, fmt.Errorf("continue session %s: %w", s.ID, err)
	}
	s.LastActivity = now

}

// promptRequest is the fixed shape POST /sessions/{id}/prompt accepts: one
// field, which is the text to deliver (contracts/http-api.md).
//
// There is deliberately no session field. Which session a prompt is for is
// settled by the path and the credential presented for it, both of which layer 3
// has already checked; a body that could name a session would be a second answer
// to that question, free to disagree with the first.
type promptRequest struct {
	// Text is data, not a command. It is length-bounded by CRSW_MAX_BODY_BYTES
	// and required to be non-empty, and that is the whole of its validation
	// (FR-030): it is delivered byte-for-byte, so anything this handler
	// "sanitised" would be a prompt the caller did not send.
	Text string `json:"text"`
}

// promptResponse is the contract's 202 body. It carries the daemon's own ID for
// the session and no echo of the text — which is not merely unnecessary but
// forbidden: prompt text is secret under docs/security.md §3, and a response
// that repeats it is one more place it can be logged by whatever reads it.
//
// ParkedOn and SuspiciousDialog are additive (PR #150 follow-up). `delivered`
// keeps meaning exactly what it always has — the keystrokes reached the pane —
// because that claim was never false; what was false is a caller reading it as
// "reached a prompt". Both new fields default to their zero value and are
// omitted then, so a caller checking only `delivered` sees byte-for-byte the
// response it always has.
type promptResponse struct {
	ID        string `json:"id"`
	Delivered bool   `json:"delivered"`

	// ParkedOn names the internal/session/dialog.go signature the pane matched
	// at the moment this prompt was delivered — set only then. It is a fixed
	// registry name (`"workspace-trust"`, `"rc-menu"`), never pane text: naming
	// which known dialog a keystroke landed in is not the secret docs/security.md
	// §3 protects, and pane content still never appears in this response.
	ParkedOn string `json:"parked_on,omitempty"`

	// SuspiciousDialog is true when the pane looked dialog-shaped — one of
	// dialog.go's generic markers matched — but no signature named it. A
	// caller should treat this exactly as it would a non-empty ParkedOn: the
	// keystrokes did not reach an ordinary prompt. There is no name to give
	// because the registry has not catalogued this one (see dialog.go's own
	// comment on why "unknown" must never collapse into "delivered as usual").
	SuspiciousDialog bool `json:"suspicious_dialog,omitempty"`
}

// outputResponse is the contract's 200 body for GET /sessions/{id}/output, in
// the contract's field order.
//
// Text is pane content: everything the session printed, which is untrusted and
// secret at once. It is a plain string in a JSON document and nothing else — no
// HTML, no markup, no ANSI passed through for a client to interpret — because
// this is the value milestone 2 will put in a browser, and Principle VII closes
// that surface by construction rather than by sanitising later.
type outputResponse struct {
	ID         string `json:"id"`
	CapturedAt string `json:"captured_at"`
	Text       string `json:"text"`

// credential issued for it, and has stamped that record's ID on the audit
// record — so this handler neither reads the path nor sets a session ID, and
// there is no version of it that could act on a session it was not given.
//
// Delivery itself belongs to internal/session, which is the only thing here that
// can cause execution on the host. What is left is the HTTP half: read the one
// field, hand it over unaltered, and answer.
//
// The dialog check reads the pane before Prompt runs, deliberately. It asks
// what the keystroke is about to land in rather than what the pane holds
// afterwards, because the keystroke itself may dismiss or change a menu —
// checking after would be asking the question once the answer had moved.
func (s *Server) promptSession(w http.ResponseWriter, r *http.Request) {
	resolved, ok := SessionFrom(r.Context())
	if !ok {
		s.failInternal(w, r, errPromptNoSession)
		return
	}

	req, ok := decode[promptRequest](s, w, r)
	if !ok {
		return
	}

	// Guarded on the same emptiness Manager.Prompt itself refuses on
	// (ErrEmptyPrompt), so that a body this route was always going to reject
	// still costs the host nothing at all — not even a read. Duplicating the
	// bare emptiness check here is not duplicating the rule: Manager.Prompt
	// still owns ErrEmptyPrompt and every other reason a prompt can be
	// refused, and refusePrompt below still asks it rather than assuming.
	var parkedOn string
	var suspicious bool
	if req.Text != "" {
		parkedOn, suspicious = s.paneDialogState(r.Context(), resolved)
	}

	if err := s.sessions.Prompt(r.Context(), resolved, req.Text); err != nil {
		s.refusePrompt(w, r, err)
		return
	}

	// 202, not 200: what is confirmed is that the keystrokes reached the pane,
	// which is not the same claim as Claude having read them, and the contract
	// spells that difference as "accepted for delivery". ParkedOn and
	// SuspiciousDialog narrow that further still: they say the keystrokes
	// reached a dialog rather than a prompt, when the pane check above found
	// one to say it about.
	s.writeJSON(w, r, http.StatusAccepted, promptResponse{
		ID:               resolved.ID,
		Delivered:        true,
